"""Char-weight allocation of cues onto a speech timeline (ms).

Ported from Transub Pro ``align_forced._allocate_on_timeline`` /
``_char_weight``. Times are absolute milliseconds on the media clock.
"""

from __future__ import annotations

import re


def char_weight(text: str) -> int:
    compact = re.sub(r"[\s　]+", "", text or "")
    return max(len(compact), 1)


def allocate_on_timeline(
    weights: list[int],
    timeline: list[tuple[int, int]],
) -> list[tuple[int, int]]:
    """Pack weighted cues into concatenated speech timeline pieces."""
    if not weights:
        return []
    if not timeline:
        return [(0, 0)] * len(weights)

    total_w = sum(weights) or len(weights)
    pieces: list[tuple[int, int]] = []
    virt = 0
    for a, b in timeline:
        dur = max(0, b - a)
        pieces.append((virt, dur))
        virt += dur
    total_dur = max(virt, len(weights) * 200)

    out: list[tuple[int, int]] = []
    cursor = 0.0
    for i, w in enumerate(weights):
        share = total_dur * (w / total_w)
        if i == len(weights) - 1:
            share = total_dur - cursor
        v0, v1 = cursor, cursor + max(share, 120)
        cursor = v1

        def virt_to_abs(v: float) -> int:
            remain = v
            for (base, dur), (abs_a, abs_b) in zip(pieces, timeline):
                if remain <= dur or (base, dur) == pieces[-1]:
                    return int(abs_a + min(remain, dur))
                remain -= dur
            return timeline[-1][1]

        a = virt_to_abs(v0)
        b = virt_to_abs(v1)
        if b <= a:
            b = a + 120
        out.append((a, b))
    return out


__all__ = ["allocate_on_timeline", "char_weight"]
